def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    opp_def = 0
    own_def = 0
    opp_last10_def = 0
    own_last10_def = 0
    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0

    for i in range(n):
        if opp[i] == 'D':
            opp_def += 1
            if i >= recent_start:
                opp_last10_def += 1
        if own[i] == 'D':
            own_def += 1
            if i >= recent_start:
                own_last10_def += 1

    last_opp = opp[-1]
    last_own = own[-1]
    remaining = 100 - n

    if last_opp == 'D':
        if last_own == 'C':
            return 'D'
        if n >= 2 and opp[-2] == 'D':
            if n >= 3 and opp[-3] == 'D':
                if remaining <= 2:
                    return 'D'
                if opp_def * 2 > n:
                    return 'D'
                if rng.random() < 0.85:
                    return 'D'
                return 'C'
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        return 'D'

    if last_own == 'D':
        if last_opp == 'C':
            if opp_def * 3 > n and n >= 6:
                if rng.random() < 0.5:
                    return 'D'
                return 'C'
            return 'C'

    if opp_def == 0:
        if n >= 95:
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    if opp_last10_def == 0:
        if remaining <= 1 and n >= 90:
            if rng.random() < 0.25:
                return 'D'
        return 'C'

    if n >= 5:
        if opp[-1] == 'C' and opp[-2] == 'C' and opp[-3] == 'D' and opp[-4] == 'C' and opp[-5] == 'C':
            if rng.random() < 0.2:
                return 'D'
            return 'C'

    if opp_last10_def >= 7:
        return 'D'
    if opp_last10_def >= 4:
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    if opp_last10_def >= 2:
        if own_last10_def == 0 and rng.random() < 0.35:
            return 'D'
        return 'C'

    if n >= 8 and opp_def * 4 < n and own_def == 0:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    if remaining <= 3 and opp_def * 4 < n:
        if rng.random() < 0.4:
            return 'D'

    return 'C'
